"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][38]={"university_physics_de:M38-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M38-L1 – Seismische Refraktion und Zweischicht-Laufzeiten<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M6: Wellenmechanik; M31: Inverse\nProbleme; M37: Astrophysik · <a\nhref=\"index.html?course=university_physics&amp;module=M37&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Direkte und kritisch refraktierte Wellen\nin einem horizontalen Zweischichtmodell vergleichen und die Gültigkeit\nvon Achsenabschnitt und kritischem Abstand erklären.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Seismische Laufzeiten enthalten Informationen über Geschwindigkeiten\nund Grenzflächen im Untergrund. Ein vereinfachtes Modell nimmt zwei\nhomogene isotrope Schichten mit ebener horizontaler Grenze an. Die\nGeschwindigkeit in Schicht zwei sei größer als in Schicht eins. Dann\nkann eine kritisch refraktierte Kopfwelle bei hinreichend großem\nQuelle–Empfänger-Abstand entstehen. Die Methode ist eine Inferenz aus\nLaufzeiten, keine direkte Aufnahme der Schichtgeometrie.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Mit Schichtgeschwindigkeiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>&gt;<\/mo><msub><mi>v<\/mi><mn>1<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">v_2&gt;v_1<\/annotation><\/semantics><\/math>,\nTiefe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>H<\/mi><annotation encoding=\"application/x-tex\">H<\/annotation><\/semantics><\/math>\nund Einfallswinkel gegen die Lotrichtung gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><mo>=<\/mo><msub><mi>v<\/mi><mn>1<\/mn><\/msub><mi>/<\/mi><msub><mi>v<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\sin i_c=v_1/v_2<\/annotation><\/semantics><\/math>.\nDie direkte Welle benötigt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><mi>x<\/mi><mi>/<\/mi><msub><mi>v<\/mi><mn>1<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">t_d=x/v_1<\/annotation><\/semantics><\/math>.\nDie Kopfwelle hat im geometrischen Strahlenmodell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mi>H<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><mi>/<\/mi><msub><mi>v<\/mi><mn>1<\/mn><\/msub><mo>+<\/mo><mi>x<\/mi><mi>/<\/mi><msub><mi>v<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">t_h(x)=2H\\cos i_c/v_1+x/v_2<\/annotation><\/semantics><\/math>,\njedoch nur für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>≥<\/mo><mn>2<\/mn><mi>H<\/mi><mrow><mi mathvariant=\"normal\">tan<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x\\ge 2H\\tan i_c<\/annotation><\/semantics><\/math>.\nDie mathematische Gerade schneidet bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=0<\/annotation><\/semantics><\/math>\ndie Zeitachse im Punkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mi>H<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><mi>/<\/mi><msub><mi>v<\/mi><mn>1<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">t_i=2H\\cos i_c/v_1<\/annotation><\/semantics><\/math>;\ndort existiert diese Wellenbahn nicht. Kritischer Abstand und\nÜberholabstand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mo>×<\/mo><\/msub><annotation encoding=\"application/x-tex\">x_{\\times}<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><msub><mi>t<\/mi><mi>h<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">t_d=t_h<\/annotation><\/semantics><\/math>\nsind verschieden.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mrow><mn>2<\/mn><mi>H<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><\/mrow><msub><mi>v<\/mi><mn>1<\/mn><\/msub><\/mfrac><mo>+<\/mo><mfrac><mi>x<\/mi><msub><mi>v<\/mi><mn>2<\/mn><\/msub><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><mo>=<\/mo><mfrac><msub><mi>v<\/mi><mn>1<\/mn><\/msub><msub><mi>v<\/mi><mn>2<\/mn><\/msub><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_h(x)=\\frac{2H\\cos i_c}{v_1}+\\frac{x}{v_2},\\qquad \\sin i_c=\\frac{v_1}{v_2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Im erfundenen Modell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">v_1=2\\,\\mathrm{km\\,s^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">v_2=4\\,\\mathrm{km\\,s^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">H=1\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>i<\/mi><mi>c<\/mi><\/msub><mo>=<\/mo><msup><mn>30<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">i_c=30^\\circ<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>i<\/mi><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>866<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_i\\approx0{,}866\\,\\mathrm s<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi mathvariant=\"normal\">min<\/mi><\/msub><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>155<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_{\\min}\\approx1{,}155\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mo>×<\/mo><\/msub><mo>≈<\/mo><mn>3<\/mn><mo>,<\/mo><mn>464<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x_{\\times}\\approx3{,}464\\,\\mathrm{km}<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x=4\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nsind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_d=2\\,\\mathrm s<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>h<\/mi><\/msub><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>866<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_h\\approx1{,}866\\,\\mathrm s<\/annotation><\/semantics><\/math>;\ndie Kopfwelle kommt zuerst. Das Diagramm zeigt Laufzeitgeraden und\nGültigkeitsbeginn getrennt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_261_DE.svg\"\nalt=\"Zeit-Abstand-Diagramm mit direkter Welle, kritisch refraktierter Kopfwelle und unterschiedenem physikalischem Anfang und Überholabstand.\" />\n<figcaption aria-hidden=\"true\">Zeit-Abstand-Diagramm mit direkter Welle,\nkritisch refraktierter Kopfwelle und unterschiedenem physikalischem\nAnfang und Überholabstand.<\/figcaption>\n<\/figure>\n<p><em>Synthetische Laufzeitrechnung eines geophysikalischen\nZweischichtmodells.<\/em><\/p>\n<p>Keine Messdaten. Die gestrichelte Gerade stellt eine unphysikalische\nExtrapolation dar.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne den Achsenabschnitt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>t<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">t_i<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">H=2\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nbei unveränderten Geschwindigkeiten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Welle trifft im Modell bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">x=2\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nzuerst ein?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wieso darf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">t_h(0)<\/annotation><\/semantics><\/math>\nnicht als reale Kopfwellenlaufzeit interpretiert werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>i<\/mi><\/msub><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>732<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_i\\approx1{,}732\\,\\mathrm s<\/annotation><\/semantics><\/math>,\nproportional zur Tiefe.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_d=1\\,\\mathrm s<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>h<\/mi><\/msub><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>366<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_h\\approx1{,}366\\,\\mathrm s<\/annotation><\/semantics><\/math>;\ndirekt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der zur Ableitung erforderliche Weg entlang der unteren Grenzfläche\nbraucht einen Mindestabstand.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das ebene Zweischichtmodell vernachlässigt Schichtneigung, laterale\nHeterogenität, Anisotropie, Dämpfung und Wellenlänge. Laufzeitinversion\nist unterbestimmt; Refraktionsmethoden können verborgene\nGeschwindigkeitslagen übersehen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die großskalige Geophysik nutzt zugleich rotierende Fluide – dazu\nführt das geostrophische Gleichgewicht. <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://uw-geophysics-edu.github.io/ess314/lectures/06_seismic_refraction_I.html\">University of Washington – Seismic Refraction I<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Zweischichtgeometrie, Grenzwinkel, kritischer Abstand und Laufzeitgeraden; eigenes Zahlenbeispiel; Fachlicher Bezug zur Lektion: M38-L1 – Seismische Refraktion und Zweischicht-Laufzeiten · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.eoas.ubc.ca/courses/eosc350/content/methods/meth_6/horizontal.html\">University of British Columbia – Seismic Refraction<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Laufzeitinterpretation und Modellannahmen bei horizontalen Grenzflächen; Fachlicher Bezug zur Lektion: M38-L1 – Seismische Refraktion und Zweischicht-Laufzeiten · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M38-L2 – Geostrophischer Wind und rotierende Strömungen<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M6: Fluidmechanik; M19:\nRotationssysteme; M38-L1 · <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die horizontale Druckgradientkraft gegen\nCoriolisterm bilanzieren und die Gültigkeitsgrenzen in den Tropen und\nder Grenzschicht angeben.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Großräumige Luft- und Meeresbewegungen werden durch Erdrotation\nabgelenkt. In Ost-Nord-Oben-Koordinaten steht die horizontale\nGeschwindigkeit des geostrophischen Idealfalls parallel zu Isobaren. Die\ngeostrophische Näherung beschreibt keine zusätzliche Kraft und nicht\njede gemessene Böe, sondern einen stationären Impulsausgleich bei\nkleinen Reibungs- und Beschleunigungstermen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"bold-italic\">𝒗<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>u<\/mi><mi>g<\/mi><\/msub><mo>,<\/mo><msub><mi>v<\/mi><mi>g<\/mi><\/msub><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf v_g=(u_g,v_g,0)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mn>2<\/mn><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>φ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f=2\\Omega\\sin\\varphi<\/annotation><\/semantics><\/math>\nund horizontalen Druckgradienten lautet das Gleichgewicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>×<\/mo><msub><mi mathvariant=\"bold-italic\">𝒗<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>−<\/mi><msub><mi>∇<\/mi><mi>h<\/mi><\/msub><mi>p<\/mi><mi>/<\/mi><mi>ρ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f\\,\\mathbf{k}\\times\\mathbf v_g=-\\nabla_h p/\\rho<\/annotation><\/semantics><\/math>.\nDamit gelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>−<\/mi><msub><mi>∂<\/mi><mi>y<\/mi><\/msub><mi>p<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ρ<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">u_g=-\\partial_y p/(\\rho f)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><msub><mi>∂<\/mi><mi>x<\/mi><\/msub><mi>p<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ρ<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v_g=\\partial_x p/(\\rho f)<\/annotation><\/semantics><\/math>.\nEin Druckabfall nach Norden erzeugt auf der Nordhalbkugel bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f&gt;0<\/annotation><\/semantics><\/math>\neinen ostwärts gerichteten geostrophischen Wind. Vertikale Hydrostatik\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>∂<\/mi><mi>z<\/mi><\/msub><mi>p<\/mi><mo>=<\/mo><mi>−<\/mi><mi>ρ<\/mi><mi>g<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial_z p=-\\rho g<\/annotation><\/semantics><\/math>\nist eine separate Näherung, keine zweite Form derselben horizontalen\nBilanz.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>×<\/mo><msub><mi mathvariant=\"bold-italic\">𝒗<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>−<\/mi><mfrac><mrow><msub><mi>∇<\/mi><mi>h<\/mi><\/msub><mi>p<\/mi><\/mrow><mi>ρ<\/mi><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>u<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>−<\/mi><mfrac><mrow><msub><mi>∂<\/mi><mi>y<\/mi><\/msub><mi>p<\/mi><\/mrow><mrow><mi>ρ<\/mi><mi>f<\/mi><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f\\,\\mathbf{k}\\times\\mathbf v_g=-\\frac{\\nabla_h p}{\\rho},\\qquad u_g=-\\frac{\\partial_y p}{\\rho f}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für die rein illustrative Wahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f=10^{-4}\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">3<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\rho=1{,}2\\,\\mathrm{kg\\,m^{-3}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>∂<\/mi><mi>y<\/mi><\/msub><mi>p<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>×<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">P<\/mi><mi mathvariant=\"normal\">a<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\partial_y p=-1{,}2\\times10^{-3}\\,\\mathrm{Pa\\,m^{-1}}<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>g<\/mi><\/msub><mo>=<\/mo><mi>+<\/mi><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">u_g=+10\\,\\mathrm{m\\,s^{-1}}<\/annotation><\/semantics><\/math>.\nDer Pluswert steht für Osten; die Coriolisbeschleunigung weist nach\nSüden und gleicht die nordwärts gerichtete Druckgradientkraft aus. Die\nGrafik zeigt Pfeilrichtungen statt realer Wetterkarten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_115_DE.svg\"\nalt=\"Horizontale Isobaren und entgegengesetzte Richtungspfeile für Druckgradientkraft, Coriolisterm und geostrophischen Ostwind.\" />\n<figcaption aria-hidden=\"true\">Horizontale Isobaren und entgegengesetzte\nRichtungspfeile für Druckgradientkraft, Coriolisterm und geostrophischen\nOstwind.<\/figcaption>\n<\/figure>\n<p><em>Vektorbilanz in Ost-Nord-Koordinaten auf der Nordhalbkugel; nicht\nskalengetreu.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie ändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>g<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_g<\/annotation><\/semantics><\/math>,\nwenn sich bei gleichem Druckgradienten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|f|<\/annotation><\/semantics><\/math>\nverdoppelt?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Richtung hat die Druckgradientkraft bei nach Norden\nabnehmendem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf die Formel für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>g<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_g<\/annotation><\/semantics><\/math>\nam Äquator nicht durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f=0<\/annotation><\/semantics><\/math>\nausgewertet werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Der Betrag halbiert sich; das Vorzeichen hängt von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nab.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Nach Norden, entgegen dem Druckgradienten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die dominante Balance wechselt; die Näherung und die Division durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nbrechen zusammen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Bilanz gilt am besten für großskalige, rotationsdominierte und\nrelativ reibungsarme Strömungen außerhalb des Äquators. In der\nplanetaren Grenzschicht, in Fronten und bei starker Krümmung sind\nageostrophische Beiträge wesentlich. Vorzeichen gelten für das benannte\nKoordinatensystem.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Drehung und leitfähige Strömung spielen auch bei der Erzeugung des\nErdmagnetfelds eine Rolle. <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://forecast.weather.gov/glossary.php?word=Geostrophic+Wind\">NOAA National Weather Service – Geostrophic Wind<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Definition des geostrophischen Winds und Parallelität zu Isobaren; Fachlicher Bezug zur Lektion: M38-L2 – Geostrophischer Wind und rotierende Strömungen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.weather.gov/source/zhu/ZHU_Training_Page/clouds/planetary_boundary_layer/PBL.html\">NOAA National Weather Service – Planetary Boundary Layer<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Reibung in der bodennahen Grenzschicht und Einschränkung der Geostrophienäherung; Fachlicher Bezug zur Lektion: M38-L2 – Geostrophischer Wind und rotierende Strömungen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M38-L3 – Geodynamo, magnetische Induktion und Diffusion<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M16: Magnetfelder; M31: partielle\nDifferentialgleichungen; M38-L2 · <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Advektion, Feldstreckung und magnetische\nDiffusion unterscheiden und die magnetische Reynolds-Zahl für ein\nkünstliches Modell bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Der Hauptteil des Erdmagnetfelds wird durch elektrische Ströme im\nleitfähigen flüssigen äußeren Kern erzeugt. Thermische und chemische\nAuftriebskräfte treiben Strömungen; die Rotation beeinflusst ihre\nOrganisation. Die Dynamotheorie untersucht, unter welchen Bedingungen\nsolche Strömungen ein Magnetfeld erhalten können. Eine einzige\nbeobachtete Magnetfeldkarte rekonstruiert die Kernströmungen nicht\neindeutig.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für inkompressible, elektrisch leitfähige Materie mit konstanter\nmagnetischer Diffusivität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>μ<\/mi><mn>0<\/mn><\/msub><mi>σ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\eta=1/(\\mu_0\\sigma)<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>∂<\/mi><mi>t<\/mi><\/msub><mi mathvariant=\"bold-italic\">𝑩<\/mi><mo>=<\/mo><mi>∇<\/mi><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒖<\/mi><mo>×<\/mo><mi mathvariant=\"bold-italic\">𝑩<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>η<\/mi><msup><mi>∇<\/mi><mn>2<\/mn><\/msup><mi mathvariant=\"bold-italic\">𝑩<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial_t\\mathbf B=\\nabla\\times(\\mathbf u\\times\\mathbf B)+\\eta\\nabla^2\\mathbf B<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∇<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝑩<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nabla\\cdot\\mathbf B=0<\/annotation><\/semantics><\/math>.\nDie erste rechte Seite steht für Feldtransport und -streckung, der\nzweite Term für ohmsche Diffusion. Der dimensionslose Quotient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mi>U<\/mi><mi>L<\/mi><mi>/<\/mi><mi>η<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_m=UL/\\eta<\/annotation><\/semantics><\/math>\nvergleicht beide Beiträge auf typischen Skalen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>,<\/mo><mi>L<\/mi><\/mrow><annotation encoding=\"application/x-tex\">U,L<\/annotation><\/semantics><\/math>.\nEin großer Wert allein beweist noch keinen selbsttragenden Dynamo.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>∂<\/mi><mi mathvariant=\"bold-italic\">𝑩<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>t<\/mi><\/mrow><\/mfrac><mo>=<\/mo><mi>∇<\/mi><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝒖<\/mi><mo>×<\/mo><mi mathvariant=\"bold-italic\">𝑩<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>η<\/mi><msup><mi>∇<\/mi><mn>2<\/mn><\/msup><mi mathvariant=\"bold-italic\">𝑩<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>R<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><mi>U<\/mi><mi>L<\/mi><\/mrow><mi>η<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\frac{\\partial\\mathbf B}{\\partial t}=\\nabla\\times(\\mathbf u\\times\\mathbf B)+\\eta\\nabla^2\\mathbf B,\\qquad R_m=\\frac{UL}{\\eta}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für die bewusst erfundenen Skalen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">U=10^{-4}\\,\\mathrm{m\\,s^{-1}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><msup><mn>10<\/mn><mn>6<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L=10^6\\,\\mathrm m<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\eta=2\\,\\mathrm{m^2\\,s^{-1}}<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_m=50<\/annotation><\/semantics><\/math>.\nDie induktive Zeitskala ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mi>/<\/mi><mi>U<\/mi><mo>=<\/mo><msup><mn>10<\/mn><mn>10<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L/U=10^{10}\\,\\mathrm s<\/annotation><\/semantics><\/math>,\ndie Diffusionszeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>L<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mi>η<\/mi><mo>=<\/mo><mn>5<\/mn><mo>×<\/mo><msup><mn>10<\/mn><mn>11<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L^2/\\eta=5\\times10^{11}\\,\\mathrm s<\/annotation><\/semantics><\/math>.\nDer Vergleich erlaubt keine quantitative Vorhersage des echten\nErdmagnetfelds.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_113_DE.svg\"\nalt=\"Schematischer Erdkern mit umlaufender leitfähiger Strömung, Feldlinien und Diffusionssymbol; keine Messkarte.\" />\n<figcaption aria-hidden=\"true\">Schematischer Erdkern mit umlaufender\nleitfähiger Strömung, Feldlinien und Diffusionssymbol; keine\nMesskarte.<\/figcaption>\n<\/figure>\n<p><em>Induktion gegen Diffusion im schematischen Dynamo.<\/em><\/p>\n<p>Keine reale Feld- oder Strömungsrekonstruktion.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie verändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>m<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_m<\/annotation><\/semantics><\/math>,\nwenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>U<\/mi><annotation encoding=\"application/x-tex\">U<\/annotation><\/semantics><\/math>\nhalbiert wird?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche SI-Einheit hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>η<\/mi><annotation encoding=\"application/x-tex\">\\eta<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_m=50<\/annotation><\/semantics><\/math>\nnicht automatisch eine Dynamoinstabilität?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Er sinkt auf 25.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi mathvariant=\"normal\">m<\/mi><mn mathvariant=\"normal\">2<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{m^2\\,s^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Erfasst nur einen Skalenvergleich; Geometrie, Randbedingungen,\nRückwirkung und Strömungsstruktur fehlen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Modell setzt konstante Leitfähigkeit und skalare Diffusivität\nvoraus; echte Kernströmungen sind turbulent, mehrskaliger und\nmagnetohydrodynamisch rückgekoppelt. Magnetfeldumkehrungen lassen sich\nnicht mit dieser einzigen Gleichung ohne Strömungs- und\nThermodynamikmodell vorhersagen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Vom Erdinneren wechselt der Fokus zur Energieaufnahme und -abgabe am\nOberrand der Atmosphäre. <a href=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.usgs.gov/programs/geomagnetism/introduction-geomagnetism\">U.S. Geological Survey – Introduction to Geomagnetism<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Konvektive Bewegung des leitfähigen äußeren Kerns und magnetische Feldentstehung; Fachlicher Bezug zur Lektion: M38-L3 – Geodynamo, magnetische Induktion und Diffusion · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M38-L4 – Globale Strahlungsbilanz und Klimaantrieb<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M22: Thermodynamik; M32:\nMessmethoden; M38-L2: atmosphärische Strömung · <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Den globalen Strahlungsfluss am\nAtmosphärenoberrand bilanzieren und positiven netto abwärts gerichteten\nEnergieeintrag von radiativem Gleichgewicht unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Klimasystem erhält kurzwellige Sonnenstrahlung, reflektiert einen\nAnteil und emittiert langwellige thermische Strahlung. Am\nAtmosphärenoberrand (TOA) ist der Nettofluss ein Diagnosewert der\nEnergiebilanz, nicht unmittelbar die Änderung der bodennahen Temperatur.\nAtmosphäre, Oberfläche und Ozean können vorübergehend Energie speichern\noder umverteilen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wir definieren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nexplizit positiv nach unten:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>S<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><mn>4<\/mn><mo>−<\/mo><mrow><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">N=(1-A)S_0/4-\\mathrm{OLR}<\/annotation><\/semantics><\/math>.\nHier ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\ndie planetare Albedo,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>S<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">S_0<\/annotation><\/semantics><\/math>\ndie Sonnenkonstante am angenommenen Orbit und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{OLR}<\/annotation><\/semantics><\/math>\nder global gemittelte langwellige Ausfluss. Der Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>\nentsteht aus dem Verhältnis von Kugelquerschnitt zu Kugeloberfläche. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=0<\/annotation><\/semantics><\/math>\nliegt im Mittel TOA-Strahlungsgleichgewicht vor; ein positives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nbedeutet netto aufgenommene Energie, nicht zwangsläufig sofortige\nOberflächenerwärmung um einen festen Wert.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>S<\/mi><mn>0<\/mn><\/msub><\/mrow><mn>4<\/mn><\/mfrac><mo>−<\/mo><mrow><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><mspace width=\"2.0em\"><\/mspace><mtext mathvariant=\"normal\">(positiv nach unten)<\/mtext><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N=\\frac{(1-A)S_0}{4}-\\mathrm{OLR}\\qquad\\text{(positiv nach unten)}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein konstruierter Bilanzfall mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1360<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">S_0=1360\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>30<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A=0{,}30<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><mo>=<\/mo><mn>237<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{OLR}=237\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>\nliefert aufgenommene Kurzwelleneinstrahlung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>238<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">238\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>+<\/mi><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">N=+1\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>.\nDies sind didaktische Eingaben, keine aktuellen Satellitenmesswerte. Die\nGrafik zeigt die drei Flussrichtungen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_297_DE.svg\"\nalt=\"Schematische Ein- und Ausstrahlung am Atmosphärenoberrand mit absorbierter Kurzwelleneinstrahlung und ausgehender langwelliger Strahlung.\" />\n<figcaption aria-hidden=\"true\">Schematische Ein- und Ausstrahlung am\nAtmosphärenoberrand mit absorbierter Kurzwelleneinstrahlung und\nausgehender langwelliger Strahlung.<\/figcaption>\n<\/figure>\n<p><em>Schematische Strahlungsbilanz am oberen Atmosphärenrand.<\/em><\/p>\n<p>Das Vorzeichen von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nist positiv nach unten festgelegt; alle Zahlen sind künstliche\nÜbungswerte.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nbei unveränderten Parametern und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">R<\/mi><\/mrow><mo>=<\/mo><mn>238<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{OLR}=238\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Was bewirkt eine Erhöhung der Albedo auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>31<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}31<\/annotation><\/semantics><\/math>\nbei sonst gleichen Zahlen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum enthält\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_0/4<\/annotation><\/semantics><\/math>\nund nicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>S<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">S_0<\/annotation><\/semantics><\/math>\ndie global gemittelte Solareinstrahlung?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Absorption sinkt um\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mo>,<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">3{,}4\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">N=-2{,}4\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Eine Kugel fängt Strahlung über den Querschnitt auf, verteilt sie\naber über die ganze Oberfläche.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die einfache TOA-Bilanz enthält keine spektralen Absorptionsbanden,\nzeitliche und räumliche Verteilung oder Wolkendynamik. Geostrophie\nbeschreibt horizontale Bewegung, nicht den hier verwendeten globalen\nEnergiebilanzterm. Der Strahlungstransport wird separat behandelt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Wie aus Energieflüssen eine gemessene Strahldichte wird, behandelt\nder Strahlungstransport. <a href=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ipcc.ch/report/ar6/wg1/chapter/chapter-7/\">IPCC AR6 WG I – Chapter 7, Earth Energy Budget and Feedbacks<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Strahlungsantrieb, Energiebilanz und Rückkopplung; Vorzeichen im Kurs explizit definiert; Fachlicher Bezug zur Lektion: M38-L4 – Globale Strahlungsbilanz und Klimaantrieb · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M38-L5 – Strahlungstransport, optische Tiefe und Emission<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M20: Optik; M22: Wärmestrahlung;\nM38-L4 · <a href=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Eine gerichtete skalare\nStrahlungstransportgleichung integrieren und die Annahmen Absorption,\nlokale thermische Emission und fehlende Streuung unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Spektrale Strahldichte ändert sich beim Durchgang durch ein Medium\ndurch Absorption, Emission und gegebenenfalls Streuung. Für einen eng\nbegrenzten didaktischen Fall betrachten wir eine isotherme, nicht\nstreuende Schicht mit konstantem Quellterm. Damit wird optische Tiefe\nals dimensionsloses Maß entlang des gewählten Ausbreitungswegs sichtbar,\nnicht als geografische Höhe oder universelle Wolkenzahl.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wir wählen die optische Tiefenkoordinate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>τ<\/mi><annotation encoding=\"application/x-tex\">\\tau<\/annotation><\/semantics><\/math>\nzunehmend entlang des Strahlwegs:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><msub><mi>I<\/mi><mi>ν<\/mi><\/msub><mi>/<\/mi><mi>d<\/mi><mi>τ<\/mi><mo>=<\/mo><mi>−<\/mi><msub><mi>I<\/mi><mi>ν<\/mi><\/msub><mo>+<\/mo><msub><mi>S<\/mi><mi>ν<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">dI_\\nu/d\\tau=-I_\\nu+S_\\nu<\/annotation><\/semantics><\/math>.\nBei lokaler thermodynamischer Gleichgewichtsannahme (LTE), rein\nthermischer Emission und ohne Streuung setzen wir\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>ν<\/mi><\/msub><mo>=<\/mo><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S_\\nu=B_\\nu(T)<\/annotation><\/semantics><\/math>.\nFür konstantes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nund Schichtdicke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><annotation encoding=\"application/x-tex\">\\tau_*<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><mo>=<\/mo><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/mrow><\/msub><msup><mi>e<\/mi><mrow><mi>−<\/mi><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><\/mrow><\/msup><mo>+<\/mo><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}=I_{\\nu,\\mathrm{in}}e^{-\\tau_*}+B_\\nu(T)(1-e^{-\\tau_*})<\/annotation><\/semantics><\/math>.\nFür richtungsabhängige Wege muss die geometrische Weglänge in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>τ<\/mi><annotation encoding=\"application/x-tex\">\\tau<\/annotation><\/semantics><\/math>\nenthalten sein. Bei Streuung oder nicht-LTE ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>ν<\/mi><\/msub><mo>≠<\/mo><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">S_\\nu\\ne B_\\nu<\/annotation><\/semantics><\/math>\nim Allgemeinen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><mo>=<\/mo><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/mrow><\/msub><msup><mi>e<\/mi><mrow><mi>−<\/mi><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><\/mrow><\/msup><mo>+<\/mo><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}=I_{\\nu,\\mathrm{in}}e^{-\\tau_*}+B_\\nu(T)(1-e^{-\\tau_*}).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für einen künstlichen monochromatischen Fall mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/mrow><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{in}}=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">B_\\nu=8<\/annotation><\/semantics><\/math>\nIntensitätseinheiten und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><mo>=<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>693<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau_*=\\ln 2\\approx0{,}693<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}=4<\/annotation><\/semantics><\/math>\nEinheiten. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau_*\\rightarrow0<\/annotation><\/semantics><\/math>\nverschwindet die Eigenemission dieser Schicht; bei großer Tiefe nähert\nsich die austretende Intensität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><annotation encoding=\"application/x-tex\">B_\\nu<\/annotation><\/semantics><\/math>.\nDie Skizze zeigt die Beiträge bei einer festen Frequenz.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_236_DE.svg\"\nalt=\"Strahlung durch eine isotherme Schicht: gedämpfte Einfallsstrahlung plus thermischer Quellanteil.\" />\n<figcaption aria-hidden=\"true\">Strahlung durch eine isotherme Schicht:\ngedämpfte Einfallsstrahlung plus thermischer Quellanteil.<\/figcaption>\n<\/figure>\n<p><em>Ein-Frequenz-LTE-Modell ohne Streuung, keine gemessenen\natmosphärischen Spektren.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau_*=0<\/annotation><\/semantics><\/math>\nfür beliebiges\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/mrow><\/msub><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{in}}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welcher Grenzwert folgt bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>τ<\/mi><mo>*<\/mo><\/msub><mo>→<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau_*\\rightarrow\\infty<\/annotation><\/semantics><\/math>\nfür eine isotherme Schicht?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist die Beziehung nicht unverändert auf starke Streuung\nanwendbar?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><mo>=<\/mo><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}=I_{\\nu,\\mathrm{in}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mi>ν<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/mrow><\/msub><mo>→<\/mo><msub><mi>B<\/mi><mi>ν<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">I_{\\nu,\\mathrm{out}}\\rightarrow B_\\nu(T)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Streuung koppelt Richtungen und verändert die Quellfunktion.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Formel ist spektral, isotherm, homogen, lokal-thermisch und nicht\nstreuend. Eine graue Näherung ersetzt spektrale Details durch gemittelte\nEigenschaften; sie ist keine exakte Beschreibung realer\nTreibhausgaslinien. Richtungs- und Vorzeichenkonventionen anderer\nLehrbücher können umgekehrt sein.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Aus Beobachtungen solcher Strahlungsfelder wird ein Modellzustand\ngeschätzt; dafür dient Datenassimilation. <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/12-815-atmospheric-radiation-fall-2008/\">MIT OpenCourseWare – Atmospheric Radiation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Lehrkontext zu atmosphärischem Strahlungstransport; skalare Gleichung als eigener Modellansatz; Fachlicher Bezug zur Lektion: M38-L5 – Strahlungstransport, optische Tiefe und Emission · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M38-L6 – Vierdimensionale Variationsassimilation und Kovarianzen<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M31: inverse Probleme und Numerik;\nM32: Messfehler; M38-L5 · <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Eine quadratische 4D-Var-Zielfunktion im\nlinearisierten Fall interpretieren und eine skalare Zustandskorrektur\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Numerische Wettervorhersage benötigt einen möglichst konsistenten\nAnfangszustand. Beobachtungen sind unvollständig und verrauscht; ein\nHintergrundzustand aus früheren Modellläufen trägt ebenfalls\nUnsicherheit. Variationsassimilation kombiniert diese Informationsarten\nunter Annahmen über ihre Fehler. In 4D-Var werden Beobachtungen über ein\nzeitliches Fenster an einen dynamischen Modellverlauf gekoppelt.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine linearisierte Zustandskorrektur\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\delta x<\/annotation><\/semantics><\/math>,\nHintergrundfehlerkovarianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nund Beobachtungsfehlerkovarianzen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_i<\/annotation><\/semantics><\/math>\nsei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>H<\/mi><mi>i<\/mi><\/msub><msub><mi>M<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>b<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d_i=y_i-H_iM_i(x_b)<\/annotation><\/semantics><\/math>\ndie Innovation. Mit linearisierter Abbildung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><msub><mi>H<\/mi><mi>i<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><msubsup><mi>M<\/mi><mi>i<\/mi><mi>′<\/mi><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">U_i=H_i\\,M_i^\\prime<\/annotation><\/semantics><\/math>\nminimiert man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>J<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>δ<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><mi>δ<\/mi><msup><mi>x<\/mi><mi>T<\/mi><\/msup><msup><mi>B<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>δ<\/mi><mi>x<\/mi><mo>+<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>d<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>U<\/mi><mi>i<\/mi><\/msub><mi>δ<\/mi><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><msubsup><mi>R<\/mi><mi>i<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>d<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>U<\/mi><mi>i<\/mi><\/msub><mi>δ<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">J(\\delta x)=\\tfrac12\\delta x^TB^{-1}\\delta x+\\tfrac12\\sum_i(d_i-U_i\\delta x)^TR_i^{-1}(d_i-U_i\\delta x)<\/annotation><\/semantics><\/math>.\nSind die Kovarianzen positiv definit, ist die Hesse-Matrix des\nquadratischen Modells\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>∇<\/mi><mn>2<\/mn><\/msup><mi>J<\/mi><mo>=<\/mo><msup><mi>B<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>+<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><msubsup><mi>U<\/mi><mi>i<\/mi><mi>T<\/mi><\/msubsup><msubsup><mi>R<\/mi><mi>i<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msubsup><msub><mi>U<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\nabla^2J=B^{-1}+\\sum_iU_i^TR_i^{-1}U_i<\/annotation><\/semantics><\/math>.\nDies beschreibt die inkrementelle mathematische Struktur, keine Aussage\nüber eine bestimmte aktuelle ECMWF-Softwarekonfiguration.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>J<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>δ<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mi>δ<\/mi><msup><mi>x<\/mi><mi>T<\/mi><\/msup><msup><mi>B<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>δ<\/mi><mi>x<\/mi><mo>+<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><munder><mo>∑<\/mo><mi>i<\/mi><\/munder><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>d<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>U<\/mi><mi>i<\/mi><\/msub><mi>δ<\/mi><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><msubsup><mi>R<\/mi><mi>i<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>d<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>U<\/mi><mi>i<\/mi><\/msub><mi>δ<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">J(\\delta x)=\\frac12\\delta x^TB^{-1}\\delta x+\\frac12\\sum_i(d_i-U_i\\delta x)^TR_i^{-1}(d_i-U_i\\delta x).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Im eigens gewählten eindimensionalen Ein-Zeit-Beispiel seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>b<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_b=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">B=4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">U=1<\/annotation><\/semantics><\/math>.\nEs gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>J<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>8<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>−<\/mo><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">J(x)=x^2/8+(2-x)^2/2<\/annotation><\/semantics><\/math>\nmit Minimum bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_a=1{,}6<\/annotation><\/semantics><\/math>\nund Hesse-Wert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>J<\/mi><mi>′<\/mi><mi>′<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo>+<\/mo><mn>1<\/mn><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">J\\prime\\prime=1/4+1=1{,}25<\/annotation><\/semantics><\/math>.\nDie aus dieser Quadratik abgeleitete Analysevarianz beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>J<\/mi><mi>′<\/mi><mi>′<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/J\\prime\\prime=0{,}8<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt zwei gewichtete Terme und deren Summe.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_103_DE.svg\"\nalt=\"Quadratische Zielfunktion mit Hintergrund- und Beobachtungsterm und Minimum bei x gleich 1,6.\" />\n<figcaption aria-hidden=\"true\">Quadratische Zielfunktion mit\nHintergrund- und Beobachtungsterm und Minimum bei x gleich\n1,6.<\/figcaption>\n<\/figure>\n<p><em>Künstlicher Skalarfall.<\/em><\/p>\n<p>Keine Wetterdaten, keine operative 4D-Var-Ausgabe.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welches Minimum entsteht bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">B=R=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>b<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_b=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Was passiert bei größerem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>R<\/mi><annotation encoding=\"application/x-tex\">R<\/annotation><\/semantics><\/math>\nund festem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nmit dem Einfluss der Beobachtung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weshalb müssen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>R<\/mi><annotation encoding=\"application/x-tex\">R<\/annotation><\/semantics><\/math>\nim einfachen inversen Modell positiv definit sein?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_a=1<\/annotation><\/semantics><\/math>,\nder gewichtete Mittelwert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Beobachtung wird schwächer gewichtet.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Damit die Inversen und eine eindeutige positive quadratische\nKrümmung existieren.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Praktische Datenassimilation nutzt oft nichtlineare Modelle,\nFehlerkorrelationen, Qualitätskontrolle und ungefähre Kovarianzen. Eine\neinzelne lineare Hesse-Matrix gilt nur für die angegebene\nInkrementalnäherung. Aussagen zu operativen Assimilationsfenstern oder\nEnsemblegrößen sind nicht Gegenstand dieses Modells.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Mit dem geschätzten Anfangszustand lassen sich die Folgen eines\nradiativen Antriebs modellieren. <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ecmwf.int/sites/default/files/elibrary/2023/81368-ifs-documentation-cy48r1-part-ii-data-assimilation.pdf\">ECMWF – 4D Variational Assimilation, IFS Documentation CY48R1<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Allgemeiner 4D-Var-Zielfunktionsaufbau; keine Aussage zum aktuellen Betriebssystem; Fachlicher Bezug zur Lektion: M38-L6 – Vierdimensionale Variationsassimilation und Kovarianzen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ecmwf.int/en/newsletter/175/earth-system-science/linearised-physics-heart-ecmwfs-4d-var\">ECMWF – Linearised Physics: the Heart of ECMWF’s 4D-Var<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kovarianzen, Tangenten-/Adjungiertenmodell und inkrementelles Verfahren; Fachlicher Bezug zur Lektion: M38-L6 – Vierdimensionale Variationsassimilation und Kovarianzen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M38-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M38-L7 – Klimarückkopplung und Gleichgewichts-Klimasensitivität<\/h1>\n<p><strong>Kursbereich:<\/strong> M38 – Master: Geophysik, Atmosphärenphysik und Klimamodelle<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M22: thermische Bilanz; M38-L4:\nTOA-Energiebilanz; M38-L6 · <a\nhref=\"index.html?course=university_physics&amp;module=M38&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Den Zusammenhang zwischen\nStrahlungsantrieb, positiver Rückstellkoeffizient-Konvention und\nmodellabhängiger Gleichgewichtstemperatur erklären und berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein zusätzlicher Strahlungsantrieb\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>F<\/mi><annotation encoding=\"application/x-tex\">F<\/annotation><\/semantics><\/math>\nstört die globale TOA-Bilanz. Temperaturänderung, Wasserdampf, Wolken\nund Albedo verändern ihrerseits den Nettoenergiefluss. Die\nGleichgewichts-Klimasensitivität beschreibt die langfristige globale\nOberflächentemperaturantwort auf eine CO₂-Verdopplung in einer\nfestgelegten Modell-/Bewertungsdefinition. Sie ist nicht gleich dem\nmomentanen Energieungleichgewicht und nicht mit einem einzigen Messwert\nidentisch.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wir definieren den Nettofluss\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nwie in M38-L4 positiv nach unten und wählen einen <strong>positiven\nRückstellkoeffizienten<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda&gt;0<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>F<\/mi><mo>−<\/mo><mi>λ<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N=F-\\lambda\\Delta T<\/annotation><\/semantics><\/math>.\nDas mathematische Gleichgewicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=0<\/annotation><\/semantics><\/math>\nergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>T<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">q<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>F<\/mi><mi>/<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta T_{\\mathrm{eq}}=F/\\lambda<\/annotation><\/semantics><\/math>.\nIm IPCC wird der Rückkopplungsparameter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>α<\/mi><annotation encoding=\"application/x-tex\">\\alpha<\/annotation><\/semantics><\/math>\nauch mit umgekehrtem Vorzeichen verwendet:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><mi>−<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=-\\lambda<\/annotation><\/semantics><\/math>\nfür dieselbe lokale lineare Bilanz. Beide Schreibweisen sind äquivalent,\nsolange Vorzeichen und Einheit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">K<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{W\\,m^{-2}\\,K^{-1}}<\/annotation><\/semantics><\/math>\nkonsequent bleiben.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>F<\/mi><mo>−<\/mo><mi>λ<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>T<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">q<\/mi><\/mrow><\/msub><mo>=<\/mo><mfrac><mi>F<\/mi><mi>λ<\/mi><\/mfrac><mspace width=\"1.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>λ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N=F-\\lambda\\Delta T,\\qquad \\Delta T_{\\mathrm{eq}}=\\frac{F}{\\lambda}\\quad(\\lambda&gt;0).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für einen nur zu Demonstrationszwecken angenommenen Antrieb\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mn>3<\/mn><mo>,<\/mo><mn>6<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">F=3{,}6\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">K<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=1{,}2\\,\\mathrm{W\\,m^{-2}\\,K^{-1}}<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>T<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">q<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta T_{\\mathrm{eq}}=3{,}0\\,\\mathrm K<\/annotation><\/semantics><\/math>.\nBei vorläufig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta T=1\\,\\mathrm K<\/annotation><\/semantics><\/math>\nverbleibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">W<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">m<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">2<\/mn><\/mrow><\/msup><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">N=2{,}4\\,\\mathrm{W\\,m^{-2}}<\/annotation><\/semantics><\/math>.\nDiese Parameter sind selbst gewählt und keine neuen IPCC-Schätzwerte.\nDas Diagramm vergleicht die gedachte Antriebsgerade mit dem\nGleichgewichtspunkt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_040_DE.svg\"\nalt=\"Lineare Beziehung von positiv nach unten gerichtetem TOA-Nettostrom und Temperaturänderung mit Nullstelle bei 3 K.\" />\n<figcaption aria-hidden=\"true\">Lineare Beziehung von positiv nach unten\ngerichtetem TOA-Nettostrom und Temperaturänderung mit Nullstelle bei 3\nK.<\/figcaption>\n<\/figure>\n<p><em>Rein illustrative Werte und konstanter positiver\nRückstellkoeffizient.<\/em><\/p>\n<p>Kein Fit an Klimadaten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Gleichgewichtserwärmung ergäbe sich bei gleichem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>F<\/mi><annotation encoding=\"application/x-tex\">F<\/annotation><\/semantics><\/math>\nund verdoppeltem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>λ<\/mi><annotation encoding=\"application/x-tex\">\\lambda<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welches Vorzeichen besitzt der Parameter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>α<\/mi><annotation encoding=\"application/x-tex\">\\alpha<\/annotation><\/semantics><\/math>\nin der genannten IPCC-Konvention?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weshalb beschreibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=0<\/annotation><\/semantics><\/math>\nnicht den Zeitpunkt, zu dem der Antrieb erstmals einsetzt?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1{,}5\\,\\mathrm K<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><mi>−<\/mi><mi>λ<\/mi><mo>&lt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=-\\lambda&lt;0<\/annotation><\/semantics><\/math>\nfür einen stabilen Rückstellbeitrag.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ozean und andere Speicher verzögern die Anpassung; unmittelbar nach\nder Störung ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\ngewöhnlich nicht null.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das lineare Einparameter-Modell ersetzt keine gekoppelten\nKlimamodelle: Rückkopplungen können von Zustand, Zeitskala,\nErwärmungsmuster und Antriebsart abhängen. Die Lehreinheit darf weder\ndie IPCC-Bandbreiten noch die Erderwärmung der Gegenwart allein aus der\nModellzahl 3 K ableiten.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>M38 verbindet seismische und magnetische Modelle mit rotierenden\nFluiden, Strahlung, Assimilation und Klimarückkopplung.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.ipcc.ch/report/ar6/wg1/chapter/chapter-7/\">IPCC AR6 WG I – Chapter 7, Earth Energy Budget and Feedbacks<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Strahlungsantrieb, Energiebilanz und Rückkopplung; Vorzeichen im Kurs explizit definiert; Fachlicher Bezug zur Lektion: M38-L7 – Klimarückkopplung und Gleichgewichts-Klimasensitivität · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
